+  \node[anchor=north west,font=\scriptsize] at (0.035,-0.025) {$0$};
+ \end{scope}
+ \node[font=\footnotesize] at (9.45,0.34) {$\pi v+\pi Uv+\pi U^2v=0$};
+ \node[font=\footnotesize] at (9.45,-0.03) {$\|\pi v\|=\|\pi Uv\|=\|\pi U^2v\|=1$};
+\end{tikzpicture}
